import * as OurTypes from "../src/types";
import * as OurVerification from "../src/verification";

test("verification path and segments format", () => {
  const path = new OurVerification.Path();

  path.prepend(
    new OurVerification.IndexSegment(
      <Array<OurTypes.Class>>[],
      2
    )
  );
  path.prepend(
    new OurVerification.PropertySegment(
      <OurTypes.Class>{},
      "something"
    )
  );

  expect(path.toString()).toStrictEqual(".something[2]");
});

test("verification error stores provided path", () => {
  const path = new OurVerification.Path();
  path.prepend(
    new OurVerification.PropertySegment(
      <OurTypes.Class>{},
      "idShort"
    )
  );

  const error = new OurVerification.VerificationError(
    "Some verification error",
    path
  );

  expect(error.message).toStrictEqual("Some verification error");
  expect(error.path.toString()).toStrictEqual(".idShort");
});

test("matchesDecimal returns boolean", () => {
  const resultOnEmpty = OurVerification.matchesDecimal("");
  expect(typeof resultOnEmpty).toStrictEqual("boolean");

  const resultOnSample = OurVerification.matchesDecimal("sample-value");
  expect(typeof resultOnSample).toStrictEqual("boolean");
});

